namespace RecipeCircle.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeCircle.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3–100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeCircle.Models;

namespace RecipeCircle.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Tomato sauce, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough.\n3. Spread sauce.\n4. Add mozzarella.\n5. Bake 10–12 minutes.\n6. Top with fresh basil.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Tikka spice paste, Onion, Garlic, Ginger, Canned tomatoes, Cream, Rice", Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or pan-fry chicken.\n3. Sauté onion, garlic, ginger.\n4. Add tomatoes and simmer.\n5. Stir in cream and chicken.\n6. Serve over rice.", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Taco seasoning", Steps = "1. Brown beef with taco seasoning.\n2. Warm taco shells.\n3. Fill shells with beef.\n4. Top with lettuce, tomato, cheese, and sour cream.", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 4, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Lime, Fish sauce, Tamarind paste, Sugar", Steps = "1. Soak noodles in warm water.\n2. Stir-fry shrimp.\n3. Scramble eggs.\n4. Add noodles with sauce (tamarind, fish sauce, sugar).\n5. Toss with bean sprouts.\n6. Garnish with peanuts and lime.", AverageRating = 4.6, RatingCount = 15 },
            new() { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract", Steps = "1. Melt chocolate and butter.\n2. Whisk eggs and sugar.\n3. Fold in chocolate mixture and flour.\n4. Pour into greased ramekins.\n5. Bake at 425°F for 12 minutes.\n6. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 25 },
            new() { Id = 6, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine lettuce, Croutons, Parmesan cheese, Caesar dressing, Lemon juice, Anchovy paste", Steps = "1. Wash and chop romaine.\n2. Make dressing (lemon, anchovy, garlic, egg yolk, olive oil).\n3. Toss lettuce with dressing.\n4. Add croutons and shaved Parmesan.", AverageRating = 3.9, RatingCount = 6 },
            new() { Id = 7, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Pancetta, Eggs, Parmesan, Black pepper", Steps = "1. Cook spaghetti al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with Parmesan.\n4. Toss hot pasta with pancetta.\n5. Stir in egg mixture off heat.\n6. Season with black pepper.", AverageRating = 4.7, RatingCount = 18 },
            new() { Id = 8, Title = "Mango Sticky Rice", Category = "Desserts", Ingredients = "Glutinous rice, Coconut milk, Sugar, Salt, Ripe mango", Steps = "1. Soak sticky rice overnight.\n2. Steam rice until tender.\n3. Heat coconut milk with sugar and salt.\n4. Mix half the sauce into rice.\n5. Slice mango.\n6. Serve rice topped with mango and remaining sauce.", AverageRating = 4.4, RatingCount = 10 },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

